/// <summary>
///  M.essl 19.03.2024
/// </summary>
/// <param name="_inventTransferJour">InventTransferJour</param>
/// <param name="_inventTransferTable">InventTransferTable</param>
[SubscribesTo(classStr(InventTransferUpd), delegateStr(InventTransferUpd, runDelegate))]
public static void InventTransferUpd_runDelegate(InventTransferJour _inventTransferJour, InventTransferTable _inventTransferTable)
{        
    AVASplitShipConfirmUpdateContainerDisposal AVASplitShipConfirmUpdateContainerDisposal = AVASplitShipConfirmUpdateContainerDisposal::current();

    if (AVASplitShipConfirmUpdateContainerDisposal
        && AVASplitShipConfirmUpdateContainerDisposal.whsMenuItemName)
    {
        AVAInventTransferJourContract contract;
        SRSPrintDestinationSettings settings;
        WHSRFMenuItemTable WHSRFMenuItemTable = WHSRFMenuItemTable::find(AVASplitShipConfirmUpdateContainerDisposal.whsMenuItemName);

        AVAInventTransferJourController controller = AVAInventTransferJourController::construct();
        controller.parmReportName(ssrsReportStr(AVAInventTransferJour, ReportShip));
        controller.parmShowDialog(false);
        controller.parmLoadFromSysLastValue(false);
        controller.parmReportContract().parmPrintSettings(WHSRFMenuItemTable.avaGetPrinterSettings());

        contract = controller.parmReportContract().parmRdpContract();
        contract.parmInventTransferJourRefRecId(_inventTransferJour.RecId);
        contract.parmTransferId(_inventTransferJour.TransferId);
        contract.parmVoucherId(_inventTransferJour.VoucherId);
        contract.parmTransDate(_inventTransferJour.TransDate);
        contract.parmUpdateType(_inventTransferJour.UpdateType);

        settings = controller.parmReportContract().parmPrintSettings(WHSRFMenuItemTable.avaGetPrinterSettings());

        controller.run();
    }
} 

